#include "document.h"
#include <iostream>
using namespace moon;int main(){try{Document d(2,1);d.beginStroke({0,0},0xff0000ff);d.commitStroke();d.addLayer();d.beginStroke({0,0},0x8000ff00);d.commitStroke();d.setLayerOpacity(.5);d.selectLayer(d.timeline().state().layers[0].id);d.addFrame();d.selectFrame(d.timeline().state().frames[1].id);d.beginStroke({1,0},0xffff0000);d.commitStroke();auto before=d.timeline().state().layers.size();d.mergeLayerDown();std::cerr<<"layers="<<d.timeline().state().layers.size()<<" before="<<before<<" p0="<<std::hex<<d.pixels()[0]<<" p1="<<d.pixels()[1]<<std::dec<<"\\n";if(d.timeline().state().layers.size()!=before-1||d.pixels()[1]==0)throw std::runtime_error("merge pixels");d.undo();if(d.timeline().state().layers.size()!=before)throw std::runtime_error("merge undo");Document f(2,1); f.beginStroke({0,0},0xff112233); f.commitStroke(); f.setFrameDuration(321); f.selectFrameHeader(f.frame().id); if(!f.copySelectedFrames()) throw std::runtime_error("frame copy"); auto src=f.pixels()[0]; f.deleteFrame(); if(!f.pasteCopiedFrames() || f.pixels()[0]!=src || f.frame().duration!=321) throw std::runtime_error("frame snapshot"); f.undo(); if(f.timeline().state().frames.size()!=2) throw std::runtime_error("frame undo"); std::cout<<"layer merge and frame snapshot checks passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
